<?php
require 'config.php';require 'helpers.php'; $page_title='Item details';$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT items.*,users.name reporter,users.email FROM items JOIN users ON users.id=items.user_id WHERE items.id=?");$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){http_response_code(404);require 'header.php';echo '<div class="empty-state"><h2>Item not found</h2><a href="index.php">Back to listings</a></div>';require 'footer.php';exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['claim'])){require_login();$msg=trim($_POST['message']??'');if(!$msg)$error='Please explain why you believe this item is yours.';elseif($_SESSION['user_id']==$item['user_id'])$error='You cannot claim your own listing.';else{$s=$pdo->prepare('INSERT INTO claims(item_id,claimant_id,message) VALUES(?,?,?)');$s->execute([$id,$_SESSION['user_id'],$msg]);flash('Your claim request has been sent to the reporter.');header('Location: item.php?id='.$id);exit;}}
$claims=[];if(logged_in()&&$_SESSION['user_id']==$item['user_id']){$s=$pdo->prepare('SELECT claims.*,users.name claimant,users.email FROM claims JOIN users ON users.id=claims.claimant_id WHERE item_id=? ORDER BY claims.created_at DESC');$s->execute([$id]);$claims=$s->fetchAll();}
require 'header.php';
?>
<section class="detail-page"><a class="back-link" href="index.php">← Back to listings</a><div class="detail-layout"><div class="detail-media"><?php if($item['image']): ?><img src="<?= e($item['image']) ?>" alt="<?= e($item['title']) ?>"><?php else: ?><div class="placeholder-image large"><span><?= e(category_icon($item['category'])) ?></span></div><?php endif; ?></div><div class="detail-info"><span class="status-pill <?= e($item['type']) ?>"><?= e(ucfirst($item['type'])) ?> item</span><span class="item-category"><?= e($item['category']) ?></span><h1><?= e($item['title']) ?></h1><p class="detail-description"><?= nl2br(e($item['description'])) ?></p><div class="detail-facts"><div><span>⌖</span><div><small>Location</small><strong><?= e($item['location']) ?></strong></div></div><div><span>◷</span><div><small>Date</small><strong><?= date('F j, Y',strtotime($item['item_date'])) ?></strong></div></div><div><span>◉</span><div><small>Reported by</small><strong><?= e($item['reporter']) ?></strong></div></div></div>
<?php if($item['status']!=='active'): ?><div class="notice">This listing is marked <?= e($item['status']) ?>.</div><?php elseif($item['type']==='found'): ?><div class="claim-box"><h3>Think this is yours?</h3><p>Send a claim to the person who found it. Include details that help verify ownership.</p><?php if(!logged_in()): ?><a class="btn btn-dark btn-full" href="login.php">Log in to claim</a><?php elseif($_SESSION['user_id']==$item['user_id']): ?><p class="muted">This is your listing.</p><?php else: ?><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><textarea name="message" rows="3" placeholder="Describe a detail that proves it belongs to you..." required></textarea><button class="btn btn-dark btn-full" name="claim" value="1">Send claim request</button></form><?php endif; ?></div><?php else: ?><div class="claim-box"><h3>Have you found this item?</h3><p>Contact the reporter to help return it.</p><a class="btn btn-dark btn-full" href="mailto:<?= e($item['email']) ?>?subject=Regarding%20<?= rawurlencode($item['title']) ?>">Contact reporter</a></div><?php endif; ?></div></div>
<?php if($claims): ?><section class="claims-section"><h2>Claim requests</h2><?php foreach($claims as $c): ?><div class="claim-row"><div><strong><?= e($c['claimant']) ?></strong><p><?= e($c['message']) ?></p><small><?= e($c['email']) ?> · <?= date('M j',strtotime($c['created_at'])) ?></small></div><span class="status-pill <?= e($c['status']) ?>"><?= e($c['status']) ?></span></div><?php endforeach; ?></section><?php endif; ?></section>
<?php require 'footer.php'; ?>
